<?php
namespace App\Http\Controllers;use App\Models\{Product,Brand,Document,Blog,Industry};use Illuminate\Http\Request;
class SearchController extends Controller {public function index(Request $r){$term=trim((string)$r->q);return view('search.index',['term'=>$term,'products'=>Product::with('brand')->published()->search($term)->take(20)->get(),'brands'=>Brand::where('status',1)->when($term,fn($q)=>$q->where('name','like',"%{$term}%"))->take(10)->get(),'documents'=>Document::where('status',1)->when($term,fn($q)=>$q->where('title','like',"%{$term}%"))->take(10)->get(),'blogs'=>Blog::where('status',1)->when($term,fn($q)=>$q->where('title','like',"%{$term}%"))->take(10)->get(),'industries'=>Industry::where('status',1)->when($term,fn($q)=>$q->where('name','like',"%{$term}%"))->take(10)->get()]);}}
